questions-per-session cap with coherent batch grouping/ordering in
\`grasp review\`, and a session-end cost summary + pending-question nudge
surfaced via \`Stop\`'s systemMessage. See README.md for the full picture.
\`grasp watch\` (persistent, auto-popping review) is not built.
`;

function printHelp(): void {
  process.stdout.write(HELP_TEXT);
}

/**
 * Every invocation ensures ~/.grasp/config.json and ~/.grasp/history.db
 * exist (creating them with defaults on first run) — not just debug:seed.
 * This is what makes "first run" in BUILD_PLAN.md's verification steps
 * true regardless of which command the user runs first.
 */
function ensureInitialized(repoRoot: string) {
  const loaded = loadConfig(repoRoot);
  const db = openStore();
  db.close();
  return loaded;
}

function runDebugSeed(): void {
  const repoRoot = resolveRepoRoot(process.cwd());
  const { config, globalConfigPath, repoConfigPath } = loadConfig(repoRoot);
  const db = openStore();

  const eventId = insertEvent(
    db,
    {
      timestamp: new Date().toISOString(),
      repo: repoRoot,
      sessionId: null,
      diffHash: "debug-seed-hash",
      diffSummary: "1 file changed, 4 insertions(+), 1 deletion(-)",
      questionConcept:
        "What's the difference between a mutex and a channel for coordinating goroutines?",
      questionInstance: "Given that, why did this change protect `cache` with a mutex?",
      questionType: "both",
      generationSource: "debug:seed",
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: 0.0031,
      diffFiles: [
        {
          path: "cache.go",
          oldPath: null,
          status: "modified",
          insertions: 4,
          deletions: 1,
          hunks: [
            {
              header: "@@ -10,5 +10,8 @@ type Cache struct {",
              lines: [
                " type Cache struct {",
                "-  data map[string]string",
                "+  mu   sync.Mutex",
                "+  data map[string]string",
                " }",
              ],
            },
          ],
        },
      ],
    },
    [{ tag: "mutex-vs-channel", answered: false }]
  );

  const tags = getConceptTagsByEventId(db, eventId);

  process.stdout.write(
    [
      `Inserted debug event id=${eventId} into ${db.name}`,
      `Linked concept_tags rows: ${tags.map((t) => `id=${t.id} tag=${t.tag}`).join(", ")}`,
      `Config loaded from: ${globalConfigPath}${
        repoConfigPath ? ` (overridden by ${repoConfigPath})` : " (no repo override present)"
      }`,
      `gateMode=${config.gateMode} questionsPerSessionCap=${config.questionsPerSessionCap}`,
      "",
    ].join("\n")
  );

  db.close();
}

function runDebugAnswer(eventIdArg: string | undefined): void {
  const eventId = Number(eventIdArg);
  if (!eventIdArg || !Number.isInteger(eventId)) {
    process.stderr.write("Usage: grasp debug:answer <event-id>\n");
    process.exitCode = 1;
    return;
  }

  const db = openStore();
  try {
    const event = getEventById(db, eventId);
    if (!event) {
      process.stderr.write(`No event with id=${eventId} found in ${db.name}\n`);
      process.exitCode = 1;
      return;
    }

    const tags = markEventAnswered(db, eventId, {
      answerConcept: event.questionConcept ? "(debug:answer stub) understood" : null,
      answerInstance: event.questionInstance ? "(debug:answer stub) understood" : null,
    });

    process.stdout.write(
      [
        `Marked event id=${eventId} answered.`,
        tags.length > 0
          ? `concept_tags now answered: ${tags.join(", ")}`
          : "(this event had no linked concept_tags — nothing to mark)",
        "",
      ].join("\n")
    );
  } finally {
    db.close();
  }
}

function runDebugCapture(repoPathArg: string | undefined): void {
  if (!repoPathArg) {
    process.stderr.write("Usage: grasp debug:capture <repo-path>\n");
    process.exitCode = 1;
    return;
  }

  const adapter = new GitDiffAdapter(repoPathArg);
  const diff = adapter.checkForChanges();

  if (diff.files.length === 0) {
    process.stdout.write(`No changes detected in ${diff.repo}\n`);
    return;
  }

  const summaryLines = diff.files.map(
    (f) =>
      `  ${f.status.padEnd(8)} ${f.oldPath ? `${f.oldPath} -> ` : ""}${f.path}  (+${f.insertions}/-${f.deletions}, ${f.hunks.length} hunk${f.hunks.length === 1 ? "" : "s"})`
  );

  const { config } = loadConfig(diff.repo);
  const verdict = evaluateCapturedDiff(diff, config);
  const filterLines = verdict.passed
    ? [
        `PASSED — ${verdict.significantFiles.length} significant file(s), ${verdict.totalChangedLines} changed lines total (max single file: ${verdict.maxSingleFileChangedLines})`,
      ]
    : [`FILTERED — reason: ${verdict.reason}`];
  if (verdict.excludedFiles.length > 0) {
    filterLines.push(
      "  excluded:",
      ...verdict.excludedFiles.map((f) => `    ${f.path} (${f.reason})`)
    );
  }

  process.stdout.write(
    [
      `Captured diff for ${diff.repo} at ${diff.capturedAt}`,
      `${diff.files.length} file(s) changed:`,
      ...summaryLines,
      "",
      "--- Phase 4 filter verdict ---",
      ...filterLines,
      "",
      "--- full CapturedDiff object (JSON) ---",
      JSON.stringify(diff, null, 2),
      "",
    ].join("\n")
  );
}

function readStdin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    process.stdin.setEncoding("utf-8");
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => resolve(data));
    process.stdin.on("error", reject);
  });
}

/**
 * "There's still a pending question for this session" message, shared by
 * the PreToolUse deny reason and the Stop systemMessage nudge so the two
 * don't drift into inconsistent wording.
 */
function pendingQuestionsMessage(count: number): string {
  return `${count} question${count === 1 ? "" : "s"} waiting — run \`grasp review\` to answer ${count === 1 ? "it" : "them"}.`;
}

/**
 * Brief §3.3's "cumulative session spend visible to the user, not just
 * logged" — see DECISIONS.md's "session-end cost summary" entry for why
 * this lives on `Stop` (the only channel a hook has to say anything at
 * all) and why 4 decimal places (real per-call costs are sub-cent; 2
 * decimals would round most of them to "$0.00" and hide the exact signal
 * the cap/summary exist to surface).
 */
function costSummaryMessage(costUsd: number): string {
  return `$${costUsd.toFixed(4)} spent generating comprehension questions this session so far.`;
}

/**
 * Claude Code hook entrypoint. Must NEVER throw, hang, or exit non-zero —
 * a hook that crashes would block the user's real Claude Code session
 * regardless of gateMode. Every failure mode below is caught and
 * swallowed rather than propagated. Hooks never render UI themselves (see
 * DECISIONS.md's TTY-access finding) — they only write state and, for
 * PreToolUse under hard-gate, emit the documented deny JSON; presentation
 * always happens in a separately-launched `grasp review`.
 */
async function runInternalHook(): Promise<void> {
  let raw: string;
  try {
    raw = await readStdin();
  } catch {
    return;
  }

  let payload: ClaudeCodeHookPayload;
  try {
    payload = JSON.parse(raw);
  } catch {
    return;
  }

  const sessionId = payload.session_id;
  const eventName = payload.hook_event_name;
  const cwd = payload.cwd;
  if (!sessionId || !eventName || !cwd) {
    return;
  }

  const promptId = resolvePromptId(payload);
  // Resolved once per firing, not per hook-event branch: Claude Code's own
  // `cwd` for a session is wherever the user happened to launch it from,
  // which is often a subdirectory of the actual repo (e.g. `cd src &&
  // claude`). Config overrides, checkpoints, and the hard-gate check all
  // need to key off the repo ROOT consistently, or a repo's `.grasp.json`
  // (gate mode, caps, ignore patterns) silently stops applying the moment
  // someone's session cwd isn't the exact repo root — see DECISIONS.md's
  // "Repo-root resolution" entry for the bug this fixes.
  const repoRoot = resolveRepoRoot(cwd);
  let hookOutput: Record<string, unknown> | null = null;

  try {
    const db = openStore();
    try {
      recordHookInvocation(db, { sessionId, promptId, eventName });
      const adapter = new ClaudeCodeAdapter(db, sessionId, promptId, repoRoot);
      adapter.ensureTurnStarted();
      // Unconditional on every firing, same as ensureTurnStarted above — a
      // cheap read that only does real work (building a tree snapshot) the
      // first time this session+repo is ever seen. Must run before any
      // PostToolUse capture so the checkpoint baseline reflects the state
      // BEFORE the first tool call, not after — see DECISIONS.md's
      // "Checkpoint-based incremental capture" entry.
      adapter.ensureCheckpointSeeded();

      if (eventName === "PostToolUse") {
        adapter.checkAndCapture();
      } else if (eventName === "Stop") {
        await adapter.onSessionComplete();
        // Visibility nudge — applies in BOTH gate modes, since it's the
        // only channel a hook actually has for reaching the user (the
        // narrowly-restricted terminalSequence field aside). See
        // DECISIONS.md's "gate-check scope" entry for why this is
        // session_id-scoped, matching the hard-gate check below. The cost
        // summary is combined into the same message when both apply — see
        // DECISIONS.md's "session-end cost summary" entry for why this is
        // the one place it surfaces and why the two independently-gated
        // pieces (pending count, spend) combine rather than firing as
        // separate messages.
        const pending = getPendingQuestionsForSession(db, sessionId);
        const spentSoFar = getSessionCostUsd(db, sessionId);
        const messageParts: string[] = [];
        if (pending.length > 0) messageParts.push(pendingQuestionsMessage(pending.length));
        if (spentSoFar > 0) messageParts.push(costSummaryMessage(spentSoFar));
        if (messageParts.length > 0) {
          hookOutput = { systemMessage: messageParts.join(" ") };
        }
      } else if (eventName === "PreToolUse") {
        const { config } = loadConfig(repoRoot);
        if (config.gateMode === "hard") {
          // Deliberately the age-limited query, not getPendingQuestionsForSession
          // — see DECISIONS.md's "Stale pending question cutoff" entry for
          // why a resumed session shouldn't be blocked by work left over
          // from days ago, even though it's technically the same session_id.
          const pending = getBlockingPendingQuestionsForSession(db, sessionId);
          if (pending.length > 0) {
            hookOutput = {
              hookSpecificOutput: {
                hookEventName: "PreToolUse",
                permissionDecision: "deny",
                permissionDecisionReason: pendingQuestionsMessage(pending.length),
              },
            };
          }
        }
      }
    } finally {
      db.close();
    }
  } catch (err) {
    try {
      process.stderr.write(`grasp internal:hook: ${(err as Error).message}\n`);
    } catch {
      // even the error report must not throw
    }
    return;
  }

  if (hookOutput) {
    try {
      process.stdout.write(JSON.stringify(hookOutput));
    } catch {
      // never let a stdout write failure propagate either
    }
  }
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const command = args[0];

  ensureInitialized(process.cwd());

  if (command === undefined || command === "--help" || command === "-h") {
    printHelp();
    return;
  }

  if (command === "--version" || command === "-v") {
    process.stdout.write(`${readPackageVersion()}\n`);
    return;
  }

  if (command === "debug:seed") {
    runDebugSeed();
    return;
  }

  if (command === "debug:capture") {
    runDebugCapture(args[1]);
    return;
  }

  if (command === "debug:answer") {
    runDebugAnswer(args[1]);
    return;
  }

  if (command === "internal:hook") {
    await runInternalHook();
    return;
  }

  if (command === "init") {
    // Same repo-root resolution as the hook path (see runInternalHook) —
    // running `grasp init` from a subdirectory should install hooks and
    // write `.grasp.json` at the actual repo root, matching where
    // ClaudeCodeAdapter/loadConfig look for them, not the exact directory
    // the command happened to be run from.
    await runInit(resolveRepoRoot(process.cwd()));
    return;
  }

  if (command === "review") {
    await runReview();
    return;
  }

  process.stderr.write(`Unknown command: ${command}\n\n`);
  printHelp();
  process.exitCode = 1;
}

main().catch((err) => {
  process.stderr.write(`${(err as Error).message}\n`);
  process.exitCode = 1;
});
import * as fs from "fs";
import * as path from "path";
import { GLOBAL_CONFIG_PATH, GRASP_HOME, REPO_CONFIG_FILENAME } from "./paths";
import { GraspConfig } from "./types";

export const DEFAULT_CONFIG: GraspConfig = {
  gateMode: "soft",
  costCapUsd: 0.25,
  ignorePatterns: [],
  questionsPerSessionCap: 8,
  diffThresholds: {
    minChangedLines: 3,
    maxTotalChangedLines: 1500,
    maxSingleFileChangedLines: 800,
  },
};

export interface LoadedConfig {
  config: GraspConfig;
  globalConfigPath: string;
  repoConfigPath: string | null;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Recursively merges `override` onto `base`. Plain objects merge key-by-key;
 * arrays and primitives are replaced wholesale (a repo's `ignorePatterns`
 * override replaces the global list rather than concatenating with it —
 * see DECISIONS.md's config-merge-semantics entry). Exported (not just used
 * internally) so the test suite can exercise the merge/precedence logic
 * directly — see DECISIONS.md's "automated test suite" entry.
 */
export function deepMerge<T>(base: T, override: unknown): T {
  if (!isPlainObject(override)) return base;
  const result: any = { ...(base as any) };
  for (const key of Object.keys(override)) {
    const overrideValue = (override as Record<string, unknown>)[key];
    const baseValue = (base as any)[key];
    if (overrideValue === undefined) continue;
    if (isPlainObject(overrideValue) && isPlainObject(baseValue)) {
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      result[key] = overrideValue;
    }
  }
  return result as T;
}

function readJsonFile(filePath: string): unknown {
  const raw = fs.readFileSync(filePath, "utf-8");
  try {
    return JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `Grasp: ${filePath} exists but is not valid JSON (${(err as Error).message}). ` +
        `Fix or remove it manually — Grasp will not overwrite a file it can't parse.`
    );
  }
}

const GATE_MODES = ["soft", "hard"] as const;

const KNOWN_TOP_LEVEL_KEYS = [
  "gateMode",
  "costCapUsd",
  "ignorePatterns",
  "questionsPerSessionCap",
  "diffThresholds",
] as const;

const KNOWN_DIFF_THRESHOLD_KEYS = [
  "minChangedLines",
  "maxTotalChangedLines",
  "maxSingleFileChangedLines",
] as const;

/**
 * Validates the *shape* of an override object read from a config file —
 * each key present must have the right type/enum/range, not just be valid
 * JSON. Only checks keys that are actually present (this validates a
 * partial override, not a fully-merged GraspConfig — `DEFAULT_CONFIG`
 * itself is always valid and never runs through this).
 *
 * Found by an independent test pass: a syntactically valid config with the
 * wrong field type (e.g. `"ignorePatterns": "scripts/"` instead of an
 * array) previously reached `Array.prototype.some` deep inside the filter
 * and crashed there — well past the point where a clear, attributable error
 * could be shown, and (before `checkAndCapture`'s atomic-transaction
 * rewrite) after the checkpoint had already advanced, permanently losing
 * the diff that triggered it. Validating here, at load time, with the same
 * "throw a clear error, never silently coerce or drop the value" policy
 * already used for malformed JSON, catches it at the actual source instead.
 * See DECISIONS.md's "Config schema validation" entry.
 */
function validateConfigOverride(value: unknown, filePath: string): asserts value is Record<string, unknown> {
  if (!isPlainObject(value)) {
    throw new Error(`Grasp: ${filePath} must contain a JSON object at its top level.`);
  }

  const errors: string[] = [];

  // Found by an independent test pass: a typo'd key (e.g. "gateMod" instead
  // of "gateMode") was silently accepted and ignored — `deepMerge` only ever
  // reads keys it recognizes off the override object, so a misspelled cap,
  // threshold, or gate-mode key left the user believing their override took
  // effect (it's sitting right there in the file they wrote) while Grasp
  // silently kept running on the default. That's a safety-relevant silent
  // failure specifically for `gateMode`/the cap fields, not just a cosmetic
  // one, so unknown keys are rejected here with the same "throw a clear
  // error, never silently ignore" posture as every other validation in this
  // function, rather than merely warned about. See DECISIONS.md's "Unknown
  // config keys are rejected, not silently ignored" entry.
  for (const key of Object.keys(value)) {
    if (!(KNOWN_TOP_LEVEL_KEYS as readonly string[]).includes(key)) {
      errors.push(
        `unknown config key ${JSON.stringify(key)} (did you mean one of: ${KNOWN_TOP_LEVEL_KEYS.join(", ")}?)`
      );
    }
  }

  if (value.gateMode !== undefined && !GATE_MODES.includes(value.gateMode as any)) {
    errors.push(`gateMode must be one of ${GATE_MODES.map((m) => `"${m}"`).join(" | ")}, got ${JSON.stringify(value.gateMode)}`);
  }

  if (value.costCapUsd !== undefined) {
    if (typeof value.costCapUsd !== "number" || !Number.isFinite(value.costCapUsd) || value.costCapUsd < 0) {
      errors.push(`costCapUsd must be a non-negative number, got ${JSON.stringify(value.costCapUsd)}`);
    }
  }

  if (value.ignorePatterns !== undefined) {
    const isStringArray = Array.isArray(value.ignorePatterns) && value.ignorePatterns.every((p) => typeof p === "string");
    if (!isStringArray) {
      errors.push(`ignorePatterns must be an array of strings, got ${JSON.stringify(value.ignorePatterns)}`);
    }
  }

  if (value.questionsPerSessionCap !== undefined) {
    if (!Number.isInteger(value.questionsPerSessionCap) || (value.questionsPerSessionCap as number) < 1) {
      errors.push(`questionsPerSessionCap must be a positive integer, got ${JSON.stringify(value.questionsPerSessionCap)}`);
    }
  }

  if (value.diffThresholds !== undefined) {
    if (!isPlainObject(value.diffThresholds)) {
      errors.push(`diffThresholds must be an object, got ${JSON.stringify(value.diffThresholds)}`);
    } else {
      for (const key of Object.keys(value.diffThresholds)) {
        if (!(KNOWN_DIFF_THRESHOLD_KEYS as readonly string[]).includes(key)) {
          errors.push(
            `unknown diffThresholds key ${JSON.stringify(key)} (did you mean one of: ${KNOWN_DIFF_THRESHOLD_KEYS.join(", ")}?)`
          );
        }
      }
      for (const key of KNOWN_DIFF_THRESHOLD_KEYS) {
        const fieldValue = (value.diffThresholds as Record<string, unknown>)[key];
        if (fieldValue === undefined) continue;
        if (typeof fieldValue !== "number" || !Number.isFinite(fieldValue) || fieldValue < 0) {
          errors.push(`diffThresholds.${key} must be a non-negative number, got ${JSON.stringify(fieldValue)}`);
        }
      }
    }
  }

  if (errors.length > 0) {
    throw new Error(
      `Grasp: ${filePath} has invalid config value(s):\n` +
        errors.map((e) => `  - ${e}`).join("\n") +
        `\nFix the file manually — Grasp will not overwrite a file it can't validate.`
    );
  }
}

function readAndValidateConfigFile(filePath: string): Record<string, unknown> {
  const parsed = readJsonFile(filePath);
  validateConfigOverride(parsed, filePath);
  return parsed;
}

/**
 * Reads the global config, creating it with defaults on first run.
 * Never overwrites an existing (even malformed) file. `globalConfigPath`/
 * `graspHome` default to the real `~/.grasp` locations for every production
 * call site (none of them pass these) — the parameters exist solely so the
 * test suite can point this at a temp directory instead of touching a real
 * user's `~/.grasp`, without changing behavior for anyone else. See
 * DECISIONS.md's "automated test suite" entry.
 */
export function ensureGlobalConfigFile(
  globalConfigPath: string = GLOBAL_CONFIG_PATH,
  graspHome: string = GRASP_HOME
): GraspConfig {
  fs.mkdirSync(graspHome, { recursive: true });
  if (!fs.existsSync(globalConfigPath)) {
    fs.writeFileSync(
      globalConfigPath,
      JSON.stringify(DEFAULT_CONFIG, null, 2) + "\n",
      "utf-8"
    );
    return structuredClone(DEFAULT_CONFIG);
  }
  const parsed = readAndValidateConfigFile(globalConfigPath);
  return deepMerge(DEFAULT_CONFIG, parsed);
}

/**
 * Loads the effective config for a given repo root: global config
 * deep-merged with an optional `.grasp.json` in that directory, with
 * repo-level values winning on conflict. Only looks in `repoRoot` itself —
 * it does not walk up parent directories looking for a repo/git root
 * (see DECISIONS.md's repo-config-resolution entry). `globalConfigPath`/
 * `graspHome` are the same test-only injection points as
 * `ensureGlobalConfigFile` above — every production call site omits them.
 */
export function loadConfig(
  repoRoot: string = process.cwd(),
  globalConfigPath: string = GLOBAL_CONFIG_PATH,
  graspHome: string = GRASP_HOME
): LoadedConfig {
  const globalConfig = ensureGlobalConfigFile(globalConfigPath, graspHome);
  const repoConfigPath = path.join(repoRoot, REPO_CONFIG_FILENAME);

  if (!fs.existsSync(repoConfigPath)) {
    return { config: globalConfig, globalConfigPath, repoConfigPath: null };
  }

  const repoOverride = readAndValidateConfigFile(repoConfigPath);
  const merged = deepMerge(globalConfig, repoOverride);
  return { config: merged, globalConfigPath, repoConfigPath };
}
import { CapturedDiff, DiffFile, DiffHunk } from "./adapters/agentAdapter";
import { BASELINE_IGNORE_PATTERNS } from "./ignoreBaseline";
import { GraspConfig } from "./types";

/**
 * Purely mechanical pre-filtering (brief §5.2's mechanical half only — no
 * semantic "is this interesting" judgment lives here; see DECISIONS.md's
 * "Flagged-pattern filtering" entry from Phase 4's planning and the
 * formatting-only/filtered-diff-recording entries added in this phase).
 */

export type FilterReason =
  | "baseline_ignore"
  | "user_ignore_pattern"
  | "generated_file"
  | "formatting_only"
  | "below_min_threshold"
  | "above_max_threshold";

export type FileExclusionReason =
  | "baseline_ignore"
  | "user_ignore_pattern"
  | "generated_file"
  | "formatting_only";

export interface ExcludedFile {
  path: string;
  reason: FileExclusionReason;
}

export interface FilterResult {
  passed: boolean;
  reason: FilterReason | null;
  /**
   * Files that survived exclusion — what a future Phase 5 should actually
   * operate on. Empty whenever `passed` is false.
   */
  significantFiles: DiffFile[];
  excludedFiles: ExcludedFile[];
  totalChangedLines: number;
  maxSingleFileChangedLines: number;
}

// --- Ignore-pattern matching -------------------------------------------

/**
 * A pattern ending in "/" matches a directory anywhere in the path (e.g.
 * "node_modules/" matches "packages/a/node_modules/x.js"). Anything else
 * matches by exact basename or exact full relative path (e.g.
 * "package-lock.json" matches both "package-lock.json" and
 * "packages/a/package-lock.json"). No glob syntax — see DECISIONS.md's
 * "Ignore-pattern matching syntax" entry for why.
 */
export function matchesIgnorePattern(filePath: string, pattern: string): boolean {
  const normalizedPath = filePath.replace(/\\/g, "/").replace(/^\.\//, "");
  if (pattern.endsWith("/")) {
    const dirName = pattern.slice(0, -1);
    const dirSegments = normalizedPath.split("/").slice(0, -1);
    return dirSegments.includes(dirName);
  }
  const basename = normalizedPath.split("/").pop() ?? normalizedPath;
  return basename === pattern || normalizedPath === pattern;
}

function classifyIgnoreExclusion(filePath: string, config: GraspConfig): FileExclusionReason | null {
  if (BASELINE_IGNORE_PATTERNS.some((p) => matchesIgnorePattern(filePath, p))) {
    return "baseline_ignore";
  }
  if (config.ignorePatterns.some((p) => matchesIgnorePattern(filePath, p))) {
    return "user_ignore_pattern";
  }
  return null;
}

// --- Generated-file detection -------------------------------------------

/**
 * Common conventions generators (protobuf/gRPC, OpenAPI, ORMs, `git`
 * itself, etc.) use to mark a file as machine-written, checked
 * case-insensitively against a file's own added content rather than a
 * fixed path/extension list — README already advertises "generated files"
 * as excluded, but the only prior implementation was a small hardcoded
 * baseline path list (lockfiles, `dist/`, `build/`), which misses any
 * generated file living somewhere else, e.g. `src/api.generated.ts`. See
 * DECISIONS.md's "Generated-file content detection" entry.
 */
const GENERATED_FILE_MARKERS: RegExp[] = [
  /auto-?generated/i,
  /do not edit/i,
  /code generated by/i,
  /this file (?:is|was) automatically generated/i,
  /@generated\b/i,
];

/**
 * How many lines from the top of the NEW file a generated-file marker has
 * to appear within to count. These markers conventionally live in a header
 * comment at the very top of a file (see e.g. the protoc-gen-ts example
 * above) — this is a position-in-the-FILE check, not a position-in-the-diff
 * one; see `isFileGenerated`'s own comment for why that distinction matters.
 */
const GENERATED_FILE_HEADER_LINE_LIMIT = 5;

/** Extracts the new-file starting line number `c` from a hunk header of the form `@@ -a[,b] +c[,d] @@`. Returns null if the header doesn't match the expected shape. */
function parseHunkNewFileStartLine(header: string): number | null {
  const match = header.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
  return match ? parseInt(match[1], 10) : null;
}

/**
 * True if a generated-file marker appears among the diff's added lines
 * AND that line falls within the first `GENERATED_FILE_HEADER_LINE_LIMIT`
 * lines of the resulting NEW file — not merely within the first few added
 * lines of whichever hunk happens to appear first in the diff.
 *
 * Originally implemented as "check the first 5 added lines of the diff,
 * wherever they fall" — found by an independent test pass to be a broad
 * false positive: an ordinary hunk touching, say, line 100 of an existing
 * file (e.g. `throw new Error("Do not edit locked state")`, a normal
 * runtime guard, not a generator's header comment) was misclassified as
 * `generated_file` and its entire otherwise-meaningful change silently
 * discarded, purely because it happened to be the first hunk in that
 * particular diff. The actual convention these markers rely on (protobuf/
 * gRPC, OpenAPI, ORMs, `git` itself) is a comment at the top of the FILE,
 * not the top of whatever diff happens to touch it — so this now tracks
 * each hunk's own new-file line numbers (from its `@@ -a,b +c,d @@` header)
 * while walking its lines, and only tests a marker against lines whose
 * real position in the resulting file is within the header window. A hunk
 * whose header start is already past that window is skipped entirely
 * without inspecting its content, so a change deep in an existing file can
 * never trigger this regardless of what its first few added lines say.
 */
export function isFileGenerated(file: DiffFile): boolean {
  for (const h of file.hunks) {
    const startLine = parseHunkNewFileStartLine(h.header);
    if (startLine === null || startLine > GENERATED_FILE_HEADER_LINE_LIMIT) continue;

    let lineNo = startLine;
    for (const line of h.lines) {
      if (line.startsWith("+") && !line.startsWith("+++")) {
        if (lineNo <= GENERATED_FILE_HEADER_LINE_LIMIT) {
          const content = line.slice(1);
          if (GENERATED_FILE_MARKERS.some((re) => re.test(content))) return true;
        }
        lineNo++;
      } else if (line.startsWith("-") && !line.startsWith("---")) {
        // Removed lines don't exist in the new file — they don't advance
        // the new-file line counter.
      } else {
        // Context line: present in both old and new file, advances the
        // new-file counter too.
        lineNo++;
      }
    }
  }
  return false;
}

// --- Formatting-only detection ------------------------------------------

/**
 * Collapses insignificant whitespace: trims the line and collapses any run
 * of internal whitespace to a single space. Reindentation, trailing
 * whitespace, and tabs-vs-spaces all normalize identically; anything that
 * changes actual tokens does not.
 */
function normalizeLine(line: string): string {
  return line.trim().replace(/\s+/g, " ");
}

/** A hunk's removed lines (with their `-` prefix stripped), normalized, in order. */
function normalizedRemovedLines(hunk: DiffHunk): string[] {
  return hunk.lines
    .filter((l) => l.startsWith("-") && !l.startsWith("---"))
    .map((l) => normalizeLine(l.slice(1)));
}

/** A hunk's added lines (with their `+` prefix stripped), normalized, in order. */
function normalizedAddedLines(hunk: DiffHunk): string[] {
  return hunk.lines
    .filter((l) => l.startsWith("+") && !l.startsWith("+++"))
    .map((l) => normalizeLine(l.slice(1)));
}

function arraysEqual(a: string[], b: string[]): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

/** Every character with any whitespace removed entirely — used only as the reflow fallback below, never as the primary comparison (see its call site's comment for why). */
function stripAllWhitespace(lines: string[]): string {
  return lines.join("").replace(/\s+/g, "");
}

/**
 * A hunk is formatting-only if its normalized removed-line sequence exactly
 * equals its normalized added-line sequence (same content, same order —
 * order matters so a real reordering of statements is never mistaken for
 * formatting). A hunk with no removed/added lines at all (shouldn't happen
 * in practice, but) counts as formatting-only vacuously.
 *
 * That per-line check requires the same NUMBER of lines on each side, so it
 * misses a common formatter behavior: reflowing one line across several
 * (or several into one) with no token change, e.g. `return input.trim();`
 * wrapped onto two lines. As a fallback specifically for that case (only
 * reached when the per-line check already failed), compare the removed and
 * added blocks with ALL whitespace stripped rather than just normalized —
 * if the character sequences match exactly, the line-break placement is the
 * only difference. This does mean a change that ONLY affects whitespace
 * *inside* a token boundary (e.g. `"a  b"` -> `"a b"` in a string literal)
 * would also be misclassified as formatting-only; accepted as a rare,
 * low-stakes edge case for a mechanical pre-filter — see DECISIONS.md's
 * "Formatter-reflow detection" entry.
 */
function isHunkFormattingOnly(hunk: DiffHunk): boolean {
  const removedLines = normalizedRemovedLines(hunk);
  const addedLines = normalizedAddedLines(hunk);
  if (arraysEqual(removedLines, addedLines)) return true;
  const removedFlat = stripAllWhitespace(removedLines);
  const addedFlat = stripAllWhitespace(addedLines);
  return removedFlat.length > 0 && removedFlat === addedFlat;
}

/** A file is formatting-only only if every one of its hunks is. */
export function isFileFormattingOnly(file: DiffFile): boolean {
  if (file.hunks.length === 0) return false;
  return file.hunks.every(isHunkFormattingOnly);
}

// --- Main filter ----------------------------------------------------------

function pickEmptyReason(excludedFiles: ExcludedFile[]): FilterReason {
  // Priority: a user-specified pattern is the most intentional signal, then
  // the baseline list, then an explicit "generated" self-declaration, then
  // formatting-only (the most inferred of the four). Only matters when a
  // multi-file diff is emptied by a mix of reasons — none of Phase 4's own
  // verification scenarios hit this, but the order needs to be defined
  // rather than left to iteration order.
  if (excludedFiles.some((f) => f.reason === "user_ignore_pattern")) return "user_ignore_pattern";
  if (excludedFiles.some((f) => f.reason === "baseline_ignore")) return "baseline_ignore";
  if (excludedFiles.some((f) => f.reason === "generated_file")) return "generated_file";
  return "formatting_only";
}

/**
 * Applies Phase 4's mechanical filter to a captured diff. Two file-level
 * exclusion passes run first (ignore patterns, then formatting-only),
 * producing a "significant files" set; size thresholds are then evaluated
 * against ONLY that remaining set — so a file excluded by either pass
 * doesn't count toward or against the size thresholds. See DECISIONS.md's
 * "Diff-size thresholds: per-file exclusion, not whole-diff" entry.
 */
export function evaluateCapturedDiff(diff: CapturedDiff, config: GraspConfig): FilterResult {
  const excludedFiles: ExcludedFile[] = [];
  const significantFiles: DiffFile[] = [];

  for (const file of diff.files) {
    const ignoreReason = classifyIgnoreExclusion(file.path, config);
    if (ignoreReason) {
      excludedFiles.push({ path: file.path, reason: ignoreReason });
      continue;
    }
    if (isFileGenerated(file)) {
      excludedFiles.push({ path: file.path, reason: "generated_file" });
      continue;
    }
    if (isFileFormattingOnly(file)) {
      excludedFiles.push({ path: file.path, reason: "formatting_only" });
      continue;
    }
    significantFiles.push(file);
  }

  if (significantFiles.length === 0) {
    return {
      passed: false,
      reason: pickEmptyReason(excludedFiles),
      significantFiles: [],
      excludedFiles,
      totalChangedLines: 0,
      maxSingleFileChangedLines: 0,
    };
  }

  const fileSizes = significantFiles.map((f) => f.insertions + f.deletions);
  const totalChangedLines = fileSizes.reduce((sum, n) => sum + n, 0);
  const maxSingleFileChangedLines = Math.max(...fileSizes);

  const { minChangedLines, maxTotalChangedLines, maxSingleFileChangedLines: maxSingleFileCap } =
    config.diffThresholds;

  if (totalChangedLines > maxTotalChangedLines || maxSingleFileChangedLines > maxSingleFileCap) {
    return {
      passed: false,
      reason: "above_max_threshold",
      significantFiles: [],
      excludedFiles,
      totalChangedLines,
      maxSingleFileChangedLines,
    };
  }

  const anyFileClearsMinimum = fileSizes.some((size) => size >= minChangedLines);
  if (!anyFileClearsMinimum) {
    return {
      passed: false,
      reason: "below_min_threshold",
      significantFiles: [],
      excludedFiles,
      totalChangedLines,
      maxSingleFileChangedLines,
    };
  }

  return {
    passed: true,
    reason: null,
    significantFiles,
    excludedFiles,
    totalChangedLines,
    maxSingleFileChangedLines,
  };
}

